import { prisma } from '../../db/prisma.js';
import type { Prisma, PayoutPreparationFailure } from '@prisma/client';

export const PAYOUT_PREPARATION_FAILURE_CLASSIFICATION = 'TRANSACTION_CONFLICT_RETRY_EXHAUSTED';
export const PAYOUT_PREPARATION_RECOVERY_GUIDANCE = 'Payment preparation was stopped after repeated transaction conflicts. Refresh the Vendor\'s current financial information before trying again.';

export class PayoutFailureQueryError extends Error {}

// The invocation identifier is generated by the authenticated legacy route, not
// supplied by the caller. Replays never update the original occurrence facts.
export async function recordPayoutPreparationFailure(input: {
  invocationId: string; verifiedVendorId: string; correlationReference?: string;
}) {
  return prisma.payoutPreparationFailure.createMany({
    data: [{ invocationId: input.invocationId, historicalVendorId: input.verifiedVendorId,
      classification: PAYOUT_PREPARATION_FAILURE_CLASSIFICATION,
      correlationReference: input.correlationReference && /^[A-Za-z0-9._:-]{1,128}$/.test(input.correlationReference)
        ? input.correlationReference : null }],
    skipDuplicates: true,
  });
}

function dto(row: PayoutPreparationFailure) {
  return { id: row.id, historicalVendorId: row.historicalVendorId, occurredAt: row.occurredAt.toISOString(),
    classification: row.classification, correlationReference: row.correlationReference,
    recoveryGuidance: PAYOUT_PREPARATION_RECOVERY_GUIDANCE };
}

export function parsePayoutFailureQuery(query: unknown) {
  const values = (query ?? {}) as Record<string, unknown>;
  if (Object.keys(values).some((key) => !['vendorId', 'cursor', 'limit'].includes(key))) {
    throw new PayoutFailureQueryError('Invalid history query.');
  }
  for (const key of ['vendorId', 'cursor', 'limit']) {
    if (values[key] !== undefined && (typeof values[key] !== 'string' || !values[key] || (values[key] as string).trim() !== values[key])) {
      throw new PayoutFailureQueryError('Invalid history query.');
    }
  }
  const vendorId = values.vendorId as string | undefined;
  if (vendorId && vendorId.length > 200) throw new PayoutFailureQueryError('Invalid Vendor filter.');
  const limit = values.limit === undefined ? 25 : Number(values.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > 50 || (values.limit !== undefined && !/^\d+$/.test(values.limit as string))) {
    throw new PayoutFailureQueryError('Invalid history page size.');
  }
  return { vendorId, limit, cursor: values.cursor as string | undefined };
}

export async function listPayoutPreparationFailures(input: ReturnType<typeof parsePayoutFailureQuery>) {
  let anchor: { occurredAt: Date; id: string } | undefined;
  if (input.cursor) {
    try {
      if (input.cursor.length > 2048 || !/^[A-Za-z0-9_-]+$/.test(input.cursor)) throw new Error();
      const value = JSON.parse(Buffer.from(input.cursor, 'base64url').toString('utf8'));
      if (value.v !== 1 || value.vendorId !== (input.vendorId ?? null) || typeof value.id !== 'string' ||
          !value.id || value.id.length > 200 || typeof value.occurredAt !== 'string' ||
          new Date(value.occurredAt).toISOString() !== value.occurredAt) throw new Error();
      anchor = { id: value.id, occurredAt: new Date(value.occurredAt) };
    } catch { throw new PayoutFailureQueryError('Invalid history cursor for this Vendor scope.'); }
  }
  const where: Prisma.PayoutPreparationFailureWhereInput = {
    ...(input.vendorId ? { historicalVendorId: input.vendorId } : {}),
    ...(anchor ? { OR: [{ occurredAt: { lt: anchor.occurredAt } },
      { occurredAt: anchor.occurredAt, id: { lt: anchor.id } }] } : {}),
  };
  const rows = await prisma.payoutPreparationFailure.findMany({ where,
    orderBy: [{ occurredAt: 'desc' }, { id: 'desc' }], take: input.limit + 1 });
  const visible = rows.slice(0, input.limit);
  const last = visible.at(-1);
  return { items: visible.map(dto), nextCursor: rows.length > input.limit && last
    ? Buffer.from(JSON.stringify({ v: 1, vendorId: input.vendorId ?? null,
      occurredAt: last.occurredAt.toISOString(), id: last.id })).toString('base64url') : null };
}

export async function getPayoutPreparationFailure(id: string, vendorId?: string) {
  if (!id || id.length > 200) throw new PayoutFailureQueryError('Invalid history identity.');
  const row = await prisma.payoutPreparationFailure.findFirst({ where: { id,
    ...(vendorId ? { historicalVendorId: vendorId } : {}) } });
  return row ? dto(row) : null;
}
